#!/usr/bin/env bash
# test-cloud-footer.sh -- markers are read through the footer a Claude Code
# cloud session appends to every comment it posts (#640):
#
#   <body>
#   <!-- talos:... -->
#
#   ---
#   _Generated by [Claude Code](https://claude.ai/code)_
#
#   AC1 an approval stamp: check-approval-sha, and post-approval's duplicate check
#   AC2 the talos:spend comment: upsert-pr-comment finds it and edits it in place
#   AC3 a talos:needs-owner comment: list-needs-owner reads its question
#   AC4 a talos:attempt record: read-attempt reads it
#   AC5 a marker followed by any other text is still not a marker
#   AC6 a quoted marker in the middle of a comment that ends with the footer is not one
# Offline: the gh stub only.
set -u
. "$(dirname "$0")/helpers.sh"
make_sandbox || exit 1
use_stubs

VCS="$TALOS_ROOT/scripts/pipeline-vcs.sh"
export TALOS_RETRY_SLEEP_SCALE=0
export STUB_CURRENT_USER=bot
printf '{"vcs": {"provider": "github", "repo": "acme/widget"}}\n' > talos.pipeline.json
export PIPELINE_CONFIG="$SANDBOX/talos.pipeline.json"
SHA="aabb1122ccdd3344eeff556677889900aabb1122"
FOOT=$'\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_'
NL=$'\n'

# comments <key> <body>...: a JSON array of comments by bot, in both shapes the
# stub serves (author for the PR view, user for the REST list).
comments() {
  python3 -I -c '
import json, sys
print(json.dumps([{"id": 4000 + i, "created_at": "2026-10-01T00:00:%02dZ" % i, "body": b,
                   "author": {"login": "bot"}, "user": {"login": "bot"}}
                  for i, b in enumerate(sys.argv[1:])]))' "$@"
}
STAMP="<!-- talos:approval sha=$SHA role=qa -->"
cas() {  # comments-json -> OUT, RC
  OUT="$(STUB_PR_HEAD_SHA="$SHA" STUB_PR_BASE_REF_NAME=main STUB_PR_LABELS_JSON='[{"name":"qa:pass"}]' \
    STUB_PR_COMMENTS_JSON="$1" bash "$VCS" check-approval-sha 9 2>&1)"; RC=$?
}

# ── AC1: the approval stamp ──────────────────────────────────────────────────
cas "$(comments "qa passed${NL}${NL}${STAMP}${FOOT}")"
assert_eq "0" "$RC" "AC1 a stamp at the head followed by the footer passes check-approval-sha" "$OUT"
assert_contains "$OUT" "all approval labels are current" "AC1 ...and reads as current"
cas "$(comments "qa passed${NL}${NL}${STAMP}${FOOT}${NL}")"
assert_eq "0" "$RC" "AC1 a trailing newline after the footer changes nothing" "$OUT"
cas "$(comments "qa passed${NL}${NL}${STAMP}")"
assert_eq "0" "$RC" "AC1 control: the same stamp without the footer passes" "$OUT"

CSTORE="$SANDBOX/cs.json"
comments "qa passed${NL}${NL}${STAMP}${FOOT}" > "$CSTORE"
: > "$GH_LOG"
OUT="$(STUB_COMMENT_STORE="$CSTORE" STUB_PR_HEAD_SHA="$SHA" STUB_PR_LABELS_JSON='[{"name":"qa:pass"}]' \
  bash "$VCS" post-approval 9 qa 2>&1)"; RC=$?
assert_eq "0" "$RC" "AC1 post-approval over a stamp with the footer exits 0" "$OUT"
assert_contains "$OUT" "already exists" "AC1 post-approval's duplicate check finds the stamp through the footer"

# ── AC2: the spend comment ───────────────────────────────────────────────────
export STUB_COMMENT_STORE="$SANDBOX/store.json"
export GH_REST_LOG="$CURL_LOG"
writes() { awk -F'\t' '$4=="POST" || $4=="PATCH" {print $4 " " $1}' "$CURL_LOG" | sed 's#https://api.github.com/repos/acme/widget/##'; }
SPEND='<!-- talos:spend -->'
printf 'Spend so far: 10' > "$SANDBOX/b1"
printf 'Spend so far: 20' > "$SANDBOX/b2"
spend_seed() {
  python3 -I -c '
import json, sys
json.dump([{"id": 5001, "user": {"login": "bot"}, "created_at": "2026-10-01T00:00:00Z",
            "html_url": "https://github.com/acme/widget/pull/7#issuecomment-5001",
            "body": sys.argv[1]}], open(sys.argv[2], "w"))' "$1" "$STUB_COMMENT_STORE"
}
: > "$GH_LOG"; : > "$CURL_LOG"
spend_seed "Spend so far: 10${NL}${NL}${SPEND}${FOOT}"
OUT="$(bash "$VCS" upsert-pr-comment 7 --marker spend --body-file "$SANDBOX/b1" </dev/null 2>&1)"; RC=$?
assert_eq "0" "$RC" "AC2 upsert over a spend comment with the footer exits 0" "$OUT"
assert_contains "$OUT" "comment=unchanged" "AC2 the same body is unchanged: the footer is not part of the comparison"
assert_eq "" "$(writes)" "AC2 ...and nothing is written"
: > "$GH_LOG"; : > "$CURL_LOG"
spend_seed "Spend so far: 10${NL}${NL}${SPEND}${FOOT}"
OUT="$(bash "$VCS" upsert-pr-comment 7 --marker spend --body-file "$SANDBOX/b2" </dev/null 2>&1)"; RC=$?
assert_contains "$OUT" "comment=updated" "AC2 a new body edits the existing comment"
assert_eq "PATCH issues/comments/5001" "$(writes)" "AC2 ...with one PATCH, never a second POST"
unset STUB_COMMENT_STORE

# ── AC3: the needs-owner question ────────────────────────────────────────────
export NO_FIX="$SANDBOX/nofix"
mkdir -p "$NO_FIX"
export STUB_FIX_DIR="$NO_FIX"
export STUB_GH_ISSUES_RAW='[{"number":5,"labels":[{"name":"pipeline:needs-owner"}]}]'
comments "Pick a DB${NL}${NL}<!-- talos:needs-owner -->${FOOT}" > "$NO_FIX/comments-5.json"
OUT="$(bash "$VCS" list-needs-owner </dev/null 2>&1)"; RC=$?
assert_eq "0" "$RC" "AC3 list-needs-owner exits 0" "$OUT"
assert_eq "needs-owner n=5 kind=issue answered=no question=Pick a DB" "$OUT" \
  "AC3 the marker comment with the footer supplies the question"
comments "<!-- talos:needs-owner -->${FOOT}" > "$NO_FIX/comments-5.json"
OUT="$(bash "$VCS" list-needs-owner --json </dev/null 2>&1)"
assert_not_contains "$OUT" "Generated by" "AC3 the footer is never read as the question"
assert_not_contains "$OUT" "(no marker comment)" "AC3 a marker-only comment with the footer is still the marker comment"
unset STUB_GH_ISSUES_RAW STUB_FIX_DIR

# ── AC4: the attempt record ──────────────────────────────────────────────────
ATT='<!-- talos:attempt stage=qa count=2 total=3 -->'
ra() { OUT="$(STUB_ISSUE_COMMENTS_JSON="$1" bash "$VCS" read-attempt 42 2>/dev/null)"; RC=$?; }
ra "$(comments "Talos attempt record${NL}${ATT}${FOOT}")"
assert_eq "0" "$RC" "AC4 read-attempt exits 0"
assert_eq "stage=qa count=2 total=3" "$OUT" "AC4 an attempt record with the footer is read exactly as without it"

# ── AC5: anything else after the marker ──────────────────────────────────────
for tail in \
    $'\n\n---\n_Generated by [Someone Else](https://example.com)_' \
    $'\n\n---' \
    "${FOOT}${FOOT}" \
    "${FOOT}"$'\nmore text' \
    $'\n\nplain trailing text'; do
  cas "$(comments "qa passed${NL}${NL}${STAMP}${tail}")"
  assert_eq "1" "$RC" "AC5 a stamp followed by $(printf '%q' "$tail") is not a marker"
  ra "$(comments "Talos attempt record${NL}${ATT}${tail}")"
  assert_eq "stage= count=0 total=0" "$OUT" "AC5 an attempt record followed by $(printf '%q' "$tail") is not read"
done

# ── AC6: a quoted marker ─────────────────────────────────────────────────────
cas "$(comments "the stamp looks like${NL}${STAMP}${NL}and that is all${FOOT}")"
assert_eq "1" "$RC" "AC6 a stamp quoted mid-comment before the footer is not a marker"
ra "$(comments "quoted: ${ATT}${NL}not the last line${FOOT}")"
assert_eq "stage= count=0 total=0" "$OUT" "AC6 an attempt record quoted mid-comment before the footer is not read"

finish
